import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import type { AskQuestionInput } from '@emotely/contract';
import { MockLanguageModelV4 } from 'ai/test';
import { runSession } from './session.ts';
import type { QuestionSet, SessionClient } from './session.ts';

const set: QuestionSet = {
  id: 'test-set',
  name: 'Test set',
  questions: [
    { id: 'q-rate', text: 'How would you rate your day?', answer_type: 'rating' },
    { id: 'q-grateful', text: 'What are you grateful for?', answer_type: 'text_list', min_answers: 3 },
  ],
};

type MockContent =
  | { type: 'text'; text: string }
  | { type: 'tool-call'; toolCallId: string; toolName: string; input: string };

// Scripted model: each doGenerate call shifts the next response off the queue.
function scriptedModel(script: MockContent[][]) {
  const queue = [...script];
  return new MockLanguageModelV4({
    doGenerate: async () => {
      const content = queue.shift();
      if (!content) throw new Error('mock model script exhausted');
      const isToolCall = content.some((c) => c.type === 'tool-call');
      return {
        content,
        finishReason: { unified: isToolCall ? ('tool-calls' as const) : ('stop' as const), raw: undefined },
        usage: { inputTokens: { total: 1, noCache: 1 }, outputTokens: { total: 1, text: 1 } },
        warnings: [],
      };
    },
  });
}

const ask = (id: string, q: (typeof set.questions)[number]): MockContent => ({
  type: 'tool-call',
  toolCallId: id,
  toolName: 'ask_question',
  input: JSON.stringify({ question_id: q.id, question: q.text, answer_type: q.answer_type }),
});

const record = (id: string, questionId: string, answerType: string, value: unknown): MockContent => ({
  type: 'tool-call',
  toolCallId: id,
  toolName: 'record_answer',
  input: JSON.stringify({ question_id: questionId, answer_type: answerType, value }),
});

const complete = (id: string, summary: string): MockContent => ({
  type: 'tool-call',
  toolCallId: id,
  toolName: 'complete_session',
  input: JSON.stringify({ summary }),
});

describe('runSession', () => {
  it('walks the set in order and completes with a summary and validated answers', async () => {
    const model = scriptedModel([
      [ask('c1', set.questions[0]!)],
      [record('c2', 'q-rate', 'rating', 7)],
      [ask('c3', set.questions[1]!)],
      [record('c4', 'q-grateful', 'text_list', ['my wife', 'myself', 'Flutter'])],
      [complete('c5', 'A good day: rated 7, grateful for three things.')],
      [{ type: 'text', text: 'Done.' }],
    ]);

    const asked: AskQuestionInput[] = [];
    const client: SessionClient = {
      askQuestion: async (input) => {
        asked.push(input);
        return input.answer_type === 'rating' ? 7 : ['my wife', 'myself', 'Flutter'];
      },
    };

    const result = await runSession({ questionSet: set, client, model });

    assert.deepEqual(
      asked.map((a) => a.question_id),
      ['q-rate', 'q-grateful'],
    );
    assert.equal(result.summary, 'A good day: rated 7, grateful for three things.');
    assert.deepEqual(result.answers, {
      'q-rate': { answer_type: 'rating', value: 7 },
      'q-grateful': { answer_type: 'text_list', value: ['my wife', 'myself', 'Flutter'] },
    });
  });
});

