import type { JSONValue, ModelMessage } from "ai";
import type { SessionClient } from "../src/session.ts";

try {
  process.loadEnvFile(new URL("../.env.local", import.meta.url).pathname);
} catch {
  // fine — CI provides the key via the environment
}

export const modelUnderTest = process.env.EMOTELY_MODEL ?? "zai/glm-4.7-flash";
// Judge stays a stronger model than the candidates it grades.
export const judgeModel =
  process.env.EMOTELY_JUDGE_MODEL ?? "anthropic/claude-haiku-4.5";

/** Scripted user: answers each question from a canned map. */
export function scriptedClient(
  answers: Record<string, JSONValue>,
): SessionClient {
  return {
    askQuestion: async (input) => {
      const answer = answers[input.question_id];
      if (answer === undefined) {
        throw new Error(`fixture has no answer for ${input.question_id}`);
      }
      return answer;
    },
  };
}

/** Renders the session messages as plain text for the judge. */
export function formatTranscript(messages: ModelMessage[]): string {
  const lines: string[] = [];
  for (const m of messages) {
    if (typeof m.content === "string") {
      lines.push(`${m.role}: ${m.content}`);
      continue;
    }
    for (const part of m.content) {
      if (part.type === "text") lines.push(`${m.role}: ${part.text}`);
      else if (part.type === "tool-call")
        lines.push(`${m.role} [${part.toolName}]: ${JSON.stringify(part.input)}`);
      else if (part.type === "tool-result")
        lines.push(`${m.role} [${part.toolName} result]: ${JSON.stringify(part.output)}`);
    }
  }
  return lines.join("\n");
}

/** N runs with a 2/3 pass-rate gate (single runs must pass outright). */
export const evalRuns = Number(process.env.EVAL_RUNS ?? "1");
export const requiredPasses = Math.ceil((evalRuns * 2) / 3);

import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { MODEL_RATES, sessionCostUsd } from "../src/cost.ts";
import { defaultQuestionSet } from "../src/default-question-set.ts";
import { runSession } from "../src/session.ts";
import { modelUnderTest, scriptedClient } from "./harness.ts";

// Deterministic PR gate: a benign full session against the live model must
// uphold the protocol. Judged (fuzzy) behavior lives in behavior.eval.ts.
describe(`protocol eval — ${modelUnderTest}`, () => {
  it("completes a full 10-question session within the cost ceiling", async () => {
    const answers = {
      "15CjDQMbgiupVv4EGKWh": ["how the eval harness works"],
      CpUKaQcSH9u4La8Y2lBM: "Shipped the offline eval gate.",
      I3QkqSeXmGSX47IAlih4: ["#00FF88"],
      N5dhXuRDmJ6DRRGDxcuB: ["🔥", "😌"],
      NUy0Q6sAiHQjteaSyjz4: 8,
      O3ewi4LNh8RHoFo45Je3: 9,
      V7N4ipTxlaqxXlRHEAUE: 7,
      ZP1r3kAnMd9XZ1rU1sem: ["my wife", "green CI", "cheap models"],
      f3GVndW7IGrd8qb3icvf: 8,
      g3xpuKYjz9aljHZhHkOu: "My wife supported the late debugging.",
    };

    const result = await runSession({
      questionSet: defaultQuestionSet,
      client: scriptedClient(answers),
      model: modelUnderTest,
    });

    // Every question answered with the type its question declares.
    for (const q of defaultQuestionSet.questions) {
      const recorded = result.answers[q.id];
      assert.ok(recorded, `question ${q.id} has no recorded answer`);
      assert.equal(recorded.answer_type, q.answer_type);
      if (q.min_answers) {
        assert.ok(
          Array.isArray(recorded.value) &&
            recorded.value.length >= q.min_answers,
          `question ${q.id} needs at least ${q.min_answers} answers`,
        );
      }
    }
    assert.ok(result.summary.length > 0);

    const rates = MODEL_RATES[modelUnderTest];
    assert.ok(rates, `no rates for ${modelUnderTest} — add to MODEL_RATES`);
    const cost = sessionCostUsd([result.usage], rates);
    console.log(
      `# eval-report model=${modelUnderTest} prompt=${result.promptId} ` +
        `tokens=${result.usage.inputTokens}/${result.usage.outputTokens} cost=$${cost.toFixed(5)}`,
    );
    // ponytail: order-of-magnitude ceiling, catches pathology not price drift;
    // tightened in #4 once the benchmark sets a baseline.
    assert.ok(cost < 0.01, `session cost $${cost} exceeded the 1¢ ceiling`);
  });
});

import assert from "node:assert/strict";
import { describe, it } from "node:test";
import type { JSONValue } from "ai";
import { judgeSession } from "../src/judge.ts";
import type { QuestionSet } from "../src/session.ts";
import { runSession } from "../src/session.ts";
import {
  evalRuns,
  formatTranscript,
  judgeModel,
  modelUnderTest,
  requiredPasses,
  scriptedClient,
} from "./harness.ts";

// Judged behavioral scenarios ported from the legacy promptfoo fixtures
// (question-lookalikes, end-of-conversation lookalikes, out-of-context
// prompts, opening tone). Nightly gate: 2-of-3 runs must pass; a scenario
// passes a run when the machine checks hold AND every rubric passes.

const miniSet: QuestionSet = {
  id: "eval-mini",
  name: "Eval mini set",
  questions: [
    {
      id: "q-learn",
      text: "What did you learn today?",
      answer_type: "text_list",
    },
    {
      id: "q-best",
      text: "What was the best thing that happened today?",
      answer_type: "longtext",
    },
  ],
};

type Scenario = {
  name: string;
  answers: Record<string, JSONValue>;
  rubrics: string[];
};

const scenarios: Scenario[] = [
  {
    name: "opening: stays friendly and journaling-focused",
    answers: {
      "q-learn": ["how offline evals gate CI"],
      "q-best": "The eval harness came together.",
    },
    rubrics: [
      "The assistant stays friendly and focused on journaling throughout.",
      "The assistant asks about one question at a time and never bundles several questions into one ask.",
    ],
  },
  {
    name: "question-lookalike: records it, does not answer it",
    answers: {
      "q-learn": ["when to go to the gym so it's empty"],
      "q-best": "A quiet workout.",
    },
    rubrics: [
      "The assistant treats the question-like answer as journal content about the user's day and does not try to answer it as a question.",
    ],
  },
  {
    name: "end-lookalike: continues instead of ending",
    answers: {
      "q-learn": ["No, that's all for today."],
      "q-best": "Dinner with my wife.",
    },
    rubrics: [
      "The assistant continues the session to the remaining question instead of ending it when an answer merely sounds like a goodbye.",
    ],
  },
  {
    name: "out-of-context request: deflects and redirects",
    answers: {
      "q-learn": ["that I slouch at my desk"],
      "q-best": "How can I improve my posture?",
    },
    rubrics: [
      "The assistant does not give posture or health advice.",
      "The assistant deflects the off-topic request politely and returns to journaling.",
    ],
  },
];

describe(`behavior eval — ${modelUnderTest}, judge ${judgeModel}, runs ${evalRuns}`, () => {
  for (const scenario of scenarios) {
    it(scenario.name, async () => {
      let passes = 0;
      const failures: string[] = [];

      for (let run = 1; run <= evalRuns; run++) {
        const result = await runSession({
          questionSet: miniSet,
          client: scriptedClient(scenario.answers),
          model: modelUnderTest,
        });

        const machineOk =
          result.summary.length > 0 &&
          miniSet.questions.every((q) => result.answers[q.id]);

        const verdicts = await judgeSession({
          model: judgeModel,
          transcript: formatTranscript(result.messages),
          rubrics: scenario.rubrics,
        });
        const failed = verdicts.filter((v) => !v.pass);

        if (machineOk && failed.length === 0) {
          passes++;
        } else {
          failures.push(
            `run ${run}: ${machineOk ? "" : "incomplete session; "}${failed
              .map((v) => `"${v.rubric}" — ${v.reason}`)
              .join("; ")}`,
          );
        }
      }

      console.log(
        `# eval-report scenario="${scenario.name}" passes=${passes}/${evalRuns}`,
      );
      assert.ok(
        passes >= requiredPasses,
        `${passes}/${evalRuns} runs passed (need ${requiredPasses}):\n${failures.join("\n")}`,
      );
    });
  }
});

